#pragma once
#include <cmath>
namespace rsm { struct Vector3{float x=0,y=0,z=0;constexpr Vector3()=default;constexpr Vector3(float X,float Y,float Z):x(X),y(Y),z(Z){}Vector3 operator+(Vector3 b)const{return{x+b.x,y+b.y,z+b.z};}Vector3 operator-(Vector3 b)const{return{x-b.x,y-b.y,z-b.z};}Vector3 operator*(float s)const{return{x*s,y*s,z*s};}Vector3&operator+=(Vector3 b){x+=b.x;y+=b.y;z+=b.z;return *this;}float Dot(Vector3 b)const{return x*b.x+y*b.y+z*b.z;}Vector3 Cross(Vector3 b)const{return{x*b.z-z*b.y,z*b.x-x*b.z,x*b.y-y*b.x};}static float dot(Vector3 a,Vector3 b){return a.Dot(b);}static Vector3 cross(Vector3 a,Vector3 b){return{a.y*b.z-a.z*b.y,a.z*b.x-a.x*b.z,a.x*b.y-a.y*b.x};}float Length()const{return std::sqrt(Dot(*this));}Vector3 normalized()const{return Normalized();}float length()const{return Length();}Vector3 Normalized()const{auto l=Length();return l>0?*this*(1.0f/l):Vector3{};}}; }